/* ---------- 5.4. Печать в PDF: один комикс или все комиксы курса одним файлом ---------- */
function printDoc(html, landscape) {
  let root = $('print-root'); if (!root) { root = document.createElement('div'); root.id = 'print-root'; document.body.appendChild(root); }
  let st = $('print-page'); if (!st) { st = document.createElement('style'); st.id = 'print-page'; document.head.appendChild(st); }
  st.textContent = `@page{size:A4 ${landscape ? 'landscape' : 'portrait'};margin:12mm}`;
  root.innerHTML = html;
  root.querySelectorAll('details').forEach(d => { d.open = true; });
  root.querySelectorAll('img').forEach(im => { im.removeAttribute('loading'); });
  const dark = document.body.classList.contains('dark');
  document.body.classList.remove('dark'); document.body.classList.add('pr-on');
  const done = () => { document.body.classList.remove('pr-on'); document.body.classList.toggle('dark', dark); root.innerHTML = ''; st.textContent = ''; window.removeEventListener('afterprint', done); };
  window.addEventListener('afterprint', done);
  const imgs = [...root.querySelectorAll('img')].filter(im => !im.complete).map(im => new Promise(res => { im.onload = im.onerror = res; }));
  return Promise.race([Promise.all(imgs), new Promise(res => setTimeout(res, 15000))]).then(() => { window.print(); });
}
function comicPrint(id) { if (COMIX[id]) return printDoc(comicPage(id), true); }
const comicPage = id => { const c = COMIX[id], src = c.img === 1 ? 'k-' + id : c.img; return `<section class="pr-comic"><p class="pr-kicker">${esc(C(id).t)}</p><h1>${tr(c.t)}</h1>${src ? `<img src="assets/img/${src}.jpg" alt="">` : ''}<ol class="comic-cap">${c.p.map(x => `<li>${mx(tr(x))}</li>`).join('')}</ol><p class="small">${t('comicSrc')}: ${tr(c.src)}</p></section>`; };
/* все комиксы курса одним PDF: по одному альбомному листу на урок, в порядке тем */
function comicsPrintAll() { return printDoc(TOPICS.filter(tp => COMIX[tp.id]).map(tp => comicPage(tp.id)).join(''), true); }

/* ---------- 5.5. Весь сайт одним HTML-файлом для работы без интернета ---------- */
function offImages() {
  const set = new Set(['fact', 'trap', 'example', 'life']);
  GROUPS.forEach(g => set.add(g.id));
  Object.keys(COMIX).forEach(id => { const c = COMIX[id]; if (c.img) set.add(c.img === 1 ? 'k-' + id : c.img); });
  return [...set].map(x => `assets/img/${x}.jpg`);
}
async function offlineBuild() {
  const btn = $('off-btn'), msg = $('off-msg'), say = x => { if (msg) msg.textContent = x; };
  if (location.protocol === 'file:') { say(tr(['Сайт открыт как файл. Скачать копию можно с адреса сайта в интернете.', 'Сайт файл ретінде ашылған. Көшірмені сайттың интернеттегі мекенжайынан жүктеуге болады.', 'The site is opened as a file. Download the copy from the online address of the site.'])); return; }
  if (btn) btn.disabled = true;
  const stage = tr(['Собираю файл', 'Файлды жинап жатырмын', 'Building the file']);
  const txt = async u => { const r = await fetch(u, { cache: 'no-cache' }); if (!r.ok) throw new Error(u + ' — ' + r.status); return r.text(); };
  const uri = async (u, mime) => { const r = await fetch(u); if (!r.ok) throw new Error(u + ' — ' + r.status); const b = new Uint8Array(await r.arrayBuffer()); let s = ''; for (let i = 0; i < b.length; i += 0x8000) s += String.fromCharCode.apply(null, b.subarray(i, i + 0x8000)); return `data:${mime};base64,${btoa(s)}`; };
  const fontsIn = async (css, base) => {            // оставляем только woff2 и вшиваем его в CSS
    css = css.replace(/,\s*url\([^)]*\.(?:woff|ttf)["']?\)\s*format\(["'](?:woff|truetype)["']\)/g, '');
    const urls = [...new Set([...css.matchAll(/url\(["']?([^"')]+\.woff2)["']?\)/g)].map(m => m[1]))];
    for (const u of urls) { const d = await uri(new URL(u, new URL(base, location.href)).href, 'font/woff2'); css = css.split(u).join(d); }
    return css;
  };
  const safe = js => js.replace(/<\/(script)/gi, '<\\/$1');
  const SC = 'script';
  try {
    let html = await txt('index.html'); let step = 0;
    const links = [...html.matchAll(/<link[^>]+rel="stylesheet"[^>]*>/g)].map(m => m[0]);
    const scripts = [...html.matchAll(/<script src="([^"]+)"><\/script>/g)];
    const imgs = offImages(), total = links.length + scripts.length + imgs.length + 3, tickUp = () => say(`${stage}… ${Math.round(++step / total * 100)}%`);
    for (const tag of links) { const href = /href="([^"]+)"/.exec(tag)[1]; const css = await fontsIn(await txt(href), href); html = html.replace(tag, () => `<style>${css}</style>`); tickUp(); }
    for (const m of scripts) { const js = safe(await txt(m[1])); html = html.replace(m[0], () => `<${SC}>${js}</${SC}>`); tickUp(); }
    const jxgCss = await txt('vendor/jsxgraph/jsxgraph.css'); tickUp();
    const jxg = safe(await txt('vendor/jsxgraph/jsxgraphcore.js')); tickUp();
    const icon = await uri('favicon.svg', 'image/svg+xml'); tickUp();
    html = html.replace(/<link rel="icon"[^>]*>/, () => `<link rel="icon" href="${icon}" type="image/svg+xml">`);
    const map = {}; for (const u of imgs) { map[u] = await uri(u, 'image/jpeg'); tickUp(); }
    /* в офлайн-копии картинки лежат в OFFLINE_IMG; наблюдатель подставляет их вместо путей assets/img/… */
    const shim = `window.OFFLINE=1;window.OFFLINE_IMG=${JSON.stringify(map)};(function(){var fix=function(n){if(n.nodeType!==1)return;var l=n.matches&&n.matches('img')?[n]:[];if(n.querySelectorAll)l=l.concat([].slice.call(n.querySelectorAll('img')));l.forEach(function(im){var s=im.getAttribute('src');if(s&&OFFLINE_IMG[s])im.src=OFFLINE_IMG[s];});};new MutationObserver(function(ms){ms.forEach(function(m){[].forEach.call(m.addedNodes,fix);});}).observe(document.documentElement,{childList:true,subtree:true});})();`;
    html = html.replace('</head>', () => `<style>${jxgCss}</style>\n<${SC}>${shim}</${SC}>\n</head>`);
    html = html.replace(/<script>boot\(\)<\/script>/, () => `<${SC}>${jxg}</${SC}>\n<${SC}>boot()</${SC}>`);
    const blob = new Blob([html], { type: 'text/html;charset=utf-8' }), a = document.createElement('a');
    a.href = URL.createObjectURL(blob); a.download = 'matanaliz-offline.html'; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 60000);
    say(tr(['Готово: файл matanaliz-offline.html', 'Дайын: matanaliz-offline.html файлы', 'Done: matanaliz-offline.html']) + ` (${(blob.size / 1048576).toFixed(1)} ${tr(['МБ', 'МБ', 'MB'])})`);
    window.OFFLINE_LAST = blob;
  } catch (e) { say(tr(['Не получилось собрать файл: ', 'Файлды жинау мүмкін болмады: ', 'Could not build the file: ']) + e.message); }
  if (btn) btn.disabled = false;
}

/* ---------- 5.6. Контрольная: время идёт, даже если ученик ушёл со страницы ----------
   Раз в секунду запоминаем введённые ответы; когда время вышло на другой странице — сдаём работу автоматически. */
setInterval(() => {
  const ex = S.exam; if (!ex || ex.done || !ex.end) return;
  const here = route.id === 'exam' && route.tab === 'run' && $('exam-timer');
  if (here) { if (ex.cids) ex.items.forEach((it, i) => { const cid = ex.cids[i]; if (cid && $(cid)) { const v = readAnswer(cid); if (v != null) ex.answers[i] = v; } }); return; }
  if (Date.now() >= ex.end) { delete ex.cids; examSubmit(); toast(tr(['Время контрольной вышло — работа сдана автоматически.', 'Бақылау жұмысының уақыты бітті — жұмыс автоматты түрде тапсырылды.', 'Exam time is up — the paper was submitted automatically.'])); }
}, 1000);
